-- ============================================================
-- HRM 基础字典恢复（聘用形式 / 员工状态 / 入职状态 / 学历 / 证件类型 / 考勤等）
-- 背景：运行库 system_dict_type / system_dict_data 中仅剩 hrm_recruit_post_status，
--       其余 HRM 字典类型与数据缺失，导致后台 HRM 相关下拉框为空。
-- 做法：从基础库脚本 ruoyi-vue-pro.sql 原样提取，id 统一加 9000 前缀避免主键冲突，
--       使用 INSERT IGNORE 保证可重复执行（不覆盖库中已有数据）。
-- 执行库：ruoyi-vue-pro
-- ============================================================


-- 核对：恢复后 HRM 字典类型应达到 42 个、字典数据 167 条以上
SELECT COUNT(*) AS hrm_dict_type_count FROM `system_dict_type` WHERE `type` LIKE 'hrm%';
SELECT COUNT(*) AS hrm_dict_data_count FROM `system_dict_data` WHERE `dict_type` LIKE 'hrm%';
